templates.source:
classDiagram
  direction TB
  class User["Synthetic_NodeBase"] {
    +String id
    +String name
    +signIn()
  }
  class Order {
    +String id
    +create()
  }
  User "1" --> "many" Order : Synthetic_EdgeBase
  class SyntheticThird {
    +String code
  }

erDiagram
  direction TB
  USER ||--o{ ORDER : Synthetic_EdgeBase
  USER["Synthetic_NodeBase"] {
    string id PK
    string name
  }
  ORDER {
    string id PK
    string user_id FK
    decimal amount
  }
  SYNTHETIC_THIRD {
    string code
  }
